    "explain": "น้ำมูกข้างเดียวบอกว่าพยาธิสภาพอยู่เหนือ nasal septum ยังไม่ถึงคอหอย และกลิ่นเหม็นเป็นลักษณะของหนองที่ปนเศษอาหาร จึงเข้าได้กับ secondary sinusitis จากฝีปลายรากฟันกรามบนซี่ท้ายที่รากยื่นเข้าไปในโพรงไซนัส\n\n❌ ทำไมข้ออื่นผิด\n— guttural pouch สองข้างจะให้น้ำมูกสองข้าง ไม่ตรงกับโจทย์\n— เลือดกำเดาให้น้ำสีแดง ไม่ใช่หนองข้นกลิ่นเหม็น\n— การแพ้ฝุ่นให้น้ำมูกใสสองข้างและมักมีอาการไอร่วม\n— โรคไวรัสทางเดินหายใจมักให้น้ำมูกสองข้างและมีไข้ร่วมทั้งคอก\n\n💡 ข้างเดียวคือเหนือ septum เหม็นคือฟัน",
