    "answer": 1,
    "explain": "Roan คือขนสีขาวแทรกสม่ำเสมออยู่บนพื้นสีเดิม โดยหัวและขาส่วนล่างยังเข้มอยู่ ถ้าพื้นเป็นน้ำตาลแดงเรียก red roan ถ้าพื้นเป็นดำเรียก blue roan และสัดส่วนขนขาวจะคงที่ไม่เพิ่มตามอายุ\n\n❌ ทำไมข้ออื่นผิด\n— Grey ขนจะขาวขึ้นเรื่อยตามอายุจนเกือบขาวทั้งตัว แต่หนังยังดำ\n— Appaloosa เป็นรอยด่างขาวเป็นจุดเป็นหย่อม ไม่ใช่ขนขาวแทรกทีละเส้น\n— Cremello ขนครีมทั้งตัวพร้อมตาสีฟ้า ไม่มีพื้นสีเดิมเหลือ\n— Skewbald เป็นปื้นขาวใหญ่สลับสีอื่น มองเห็นขอบเขตชัดเจน\n\n💡 Roan คือเกลือพริกไทยบนพื้นสีเดิม หัวกับขายังเข้ม",
