    "explain": "weight tape อาศัยความสัมพันธ์ระหว่างรอบอกกับน้ำหนักตัว จึงให้ค่าประมาณเพื่อคัดกรองและติดตามแนวโน้มเท่านั้น คลาดเคลื่อนตามรูปร่าง สายพันธุ์ และภาวะท้อง ยาที่มีช่วงปลอดภัยแคบควรอิงน้ำหนักจากเครื่องชั่ง\n\n❌ ทำไมข้ออื่นผิด\n— สายวัดไม่ได้แม่นกว่าเครื่องชั่ง จึงไม่เหมาะกับยาที่ต้องการความแม่น\n— ใช้ได้กับม้าโตด้วย ไม่ได้จำกัดเฉพาะลูกม้า\n— สายวัดบางรุ่นมีสเกลวัดส่วนสูงอยู่อีกด้าน จึงไม่ใช่ว่าวัดน้ำหนักไม่ได้\n— การวัดรอบอกทำในม้าที่ยืนสงบได้ ไม่ต้องวางยาซึม\n\n💡 สายวัดไว้คัดกรองและดูแนวโน้ม เครื่องชั่งไว้คำนวณยา",
