    "explain": "ear twitch ทำให้ม้าเจ็บมาก ตอบสนองด้วยอัตราการเต้นหัวใจที่สูงขึ้นและคอร์ติซอลที่เพิ่มขึ้น ต่างจาก nose twitch ที่กระตุ้นการหลั่งเอนดอร์ฟิน ผลคือม้ากลายเป็น head shy และจับบังคับครั้งต่อไปยากขึ้น จึงเป็นทางเลือกท้ายสุด\n\n❌ ทำไมข้ออื่นผิด\n— การบิดใบหูไม่ได้ทำให้ม้าหูอื้อจนไม่ได้ยินคำสั่ง\n— เนื้อตายที่ปลายหูภายในไม่กี่นาทีไม่เกิดจากการจับบิดชั่วคราว\n— การหลั่งเอนดอร์ฟินเป็นกลไกของ nose twitch ไม่ใช่ ear twitch\n— ปัญหาหลักคือความเจ็บและผลด้านสวัสดิภาพ ไม่ใช่ผิวหนังฉีกขาด\n\n💡 บิดจมูกได้เอนดอร์ฟิน บิดหูได้คอร์ติซอลกับม้าที่กลัวหัวไปตลอด",
