    "explain": "ม้าเป็นสัตว์ที่ถูกล่า สัญชาตญาณหลักคือ flight or fight โดยเลือกหนีก่อนเป็นอันดับแรก และบางตัวที่หนีไม่ได้จะ freeze คือนิ่งค้างไปเลย ความเข้าใจข้อนี้เป็นฐานของการจับบังคับที่ปลอดภัย\n\n❌ ทำไมข้ออื่นผิด\n— ม้าเลือกหนีก่อนสู้ ขนาดตัวไม่ได้ทำให้มันเป็นผู้ล่า\n— การหมอบราบกับพื้นเป็นพฤติกรรมของสัตว์ที่พรางตัว ไม่ใช่ม้า\n— ม้าจะอยู่รวมฝูงเพื่อความปลอดภัย ไม่ได้แยกตัวออกเมื่อตกใจ\n— ม้าไม่ได้ส่งเสียงเรียกผู้ล่า แต่ส่งเสียงเรียกฝูงของตัวเอง\n\n💡 หนีก่อน สู้ทีหลัง และบางตัวค้างนิ่งไปเลย",
