    "q": "เหตุใดจึงแนะนำให้แทงเข็มเข้า jugular vein ของม้าที่บริเวณคอส่วนบนมากกว่าคอส่วนล่าง",
    "options": [
      "คอส่วนบนมีชั้นไขมันหนากว่าจึงหยุดเลือดได้เองเร็วกว่า",
      "คอส่วนบนหลอดเลือดดำอยู่ตื้นและห่างจากหลอดเลือดแดงกว่า",
      "คอส่วนบนมีเส้นประสาทน้อยกว่าจึงไม่ทำให้ม้าเจ็บเลย",
      "คอส่วนบนหลอดเลือดดำมีขนาดใหญ่กว่าคอส่วนล่างสองเท่า",
      "คอส่วนบนอยู่ไกลจากหัวใจจึงมีความดันในหลอดเลือดต่ำกว่า"
    ],
    "answer": 1,
    "explain": "ยิ่งลงมาทางคอส่วนล่าง common carotid artery กับ vagosympathetic trunk จะวิ่งชิดกับ jugular vein มากขึ้น และกล้ามเนื้อ omohyoideus ที่คั่นอยู่ก็บางลง การแทงที่คอส่วนบนราวหนึ่งในสามบนจึงลดโอกาสแทงโดนหลอดเลือดแดงและเส้นประสาท\n\n❌ ทำไมข้ออื่นผิด\n— ชั้นไขมันที่คอไม่ได้ช่วยห้ามเลือดและไม่ใช่เหตุผลในการเลือกตำแหน่ง\n— การแทงเข็มทำให้ม้าเจ็บได้ทุกตำแหน่ง ไม่มีจุดที่ไม่เจ็บเลย\n— ขนาดหลอดเลือดดำไม่ได้ต่างกันถึงสองเท่าระหว่างคอบนกับคอล่าง\n— ความดันในหลอดเลือดดำไม่ใช่เหตุผลของการเลือกตำแหน่งแทง\n\n💡 ยิ่งลงล่าง แดงกับดำยิ่งชิด แทงสูงไว้ปลอดภัยกว่า",
