    "explain": "ค่าดำรงชีพของม้าโตอยู่ที่ราว 50 ml/kg BW ต่อวัน โดยช่วงที่ใช้คือ 41 ถึง 67 ml/kg ต่อวัน คิดเป็นราว 20 ถึง 34 ลิตรต่อวันในม้าหนัก 500 กิโลกรัม\n\nสองสถานะนี้ไม่เท่ากัน การตั้งท้องไม่ทำให้ความต้องการน้ำเพิ่มขึ้นเกินค่าดำรงชีพ ส่วนแม่ม้าให้นมมีปริมาณน้ำรวม 75 ถึง 100 ml/kg BW ปัจจัยอื่นที่ทำให้ดื่มมากขึ้นคือชนิดอาหารหยาบ ปริมาณอาหารข้น อากาศร้อนชื้น และอุณหภูมิน้ำ\n\n❌ ทำไมข้ออื่นผิด\n— 10 ถึง 20 ml/kg น้อยเกินไป และการให้นมไม่ได้ลดความต้องการน้ำ\n— 100 ถึง 150 ml/kg สูงเกินค่าดำรงชีพ\n— 41 ถึง 67 ถูก แต่การให้นมทำให้เพิ่ม ไม่ใช่ลด\n— 200 ถึง 250 ml/kg สูงเกินจริงหลายเท่า\n\n⚠️ จุดที่เข้าใจผิดกันบ่อยคือเอา 75 ถึง 100 ไปผูกกับการตั้งท้อง ตัวเลขนี้เป็นของแม่ม้าให้นม\n\n💡 ท้องไม่เพิ่ม ให้นมถึงเพิ่ม",
