    "answer": 0,
    "explain": "ม้าที่ได้ปล่อยแปลงหรือมีอาหารหยาบให้ตลอดจะใช้เวลากินราวหกสิบเปอร์เซ็นต์ของวัน ถ้าสัดส่วนการยืนเฉยสูงถึงหกสิบห้าเปอร์เซ็นต์แทน แปลว่าม้าถูกขังในพื้นที่จำกัดและไม่มีอาหารหยาบให้กินต่อเนื่อง ซึ่งเป็นปัจจัยเสี่ยงของแผลในกระเพาะและพฤติกรรมผิดปกติ\n\n❌ ทำไมข้ออื่นผิด\n— ม้าที่ได้ปล่อยแปลงจะมีสัดส่วนการกินสูง ไม่ใช่การยืนสูง\n— การออกกำลังกายมากจะเพิ่มสัดส่วนหมวดอื่น ไม่ใช่การยืนเฉย\n— โรคทางเดินหายใจต้องอาศัยการตรวจร่างกาย ไม่สรุปจากเวลายืนอย่างเดียว\n— การยืนเฝ้าระวังเป็นพฤติกรรมช่วงสั้น ไม่กินเวลาถึงสองในสามของวัน\n\n💡 ม้าที่กินนานคือม้าที่มีหญ้า ม้าที่ยืนนานคือม้าที่ไม่มีอะไรทำ",
