    "explain": "Heat stress index รวมอุณหภูมิกับความชื้นสัมพัทธ์เข้าด้วยกัน เพราะความชื้นสูงทำให้เหงื่อระเหยไม่ได้ ค่าที่ได้ใช้ทำนายว่าม้าจะทนสภาพอากาศร้อนชื้นได้แค่ไหน เพื่อวางแผนเวลาออกกำลัง การให้น้ำและอิเล็กโทรไลต์ และเฝ้าระวัง heat stroke\n\n❌ ทำไมข้ออื่นผิด\n— ปริมาณอาหารข้นคำนวณจาก digestible energy ไม่ใช่ดัชนีความร้อน\n— ภาวะขาดทองแดงและสังกะสีประเมินจากอาหารและค่าเลือด ไม่ใช่ค่าอากาศ\n— ความชื้นที่ทำให้หญ้าแห้งขึ้นราคือเกณฑ์เกินยี่สิบเปอร์เซ็นต์ คนละเรื่องกัน\n— การหลั่งน้ำลายขึ้นกับจำนวนครั้งที่เคี้ยว ไม่ใช่สภาพอากาศ\n\n💡 ร้อนอย่างเดียวยังพอทน ร้อนบวกชื้นคือเหงื่อระเหยไม่ออก",
