    "explain": "ม้าเก็บน้ำปริมาณมากไว้ใน lumen ของทางเดินอาหาร โดยเฉพาะ cecum และ colon ซึ่งทำหน้าที่เป็นถังสำรองน้ำและอิเล็กโทรไลต์ ส่วนเมื่อเทียบกันเป็นเนื้อเยื่อ ปริมาณน้ำต่อน้ำหนักจะเรียงจากปอด แล้วเลือด แล้วสมอง แล้วกระดูก\n\n❌ ทำไมข้ออื่นผิด\n— กล้ามเนื้อมีมวลมากแต่ไม่ใช่แหล่งสำรองที่ใหญ่ที่สุดในม้า\n— ไขมันมีสัดส่วนน้ำต่ำที่สุดในบรรดาเนื้อเยื่อ\n— กระดูกอยู่ท้ายสุดของลำดับปริมาณน้ำต่อน้ำหนัก\n— กระแสเลือดมีปริมาตรเพียงราวแปดเปอร์เซ็นต์ของน้ำหนักตัว\n\n💡 ทางเดินอาหารของม้าคือถังน้ำเคลื่อนที่ จึงเสียน้ำเร็วมากเมื่อท้องเสีย",
