    "explain": "Psoroptidae ได้แก่ Psoroptes, Chorioptes และ Otodectes มีลำตัวรี เป็น non-burrowing mite คืออยู่บนผิวหนังไม่ขุดโพรง และขาคู่ที่สามกับสี่ยาวจนยื่นพ้นขอบลำตัวจนมองเห็นได้จากด้านบน ซึ่งช่วยแยกออกจาก Sarcoptes ที่ขุดโพรง\n\n❌ ทำไมข้ออื่นผิด\n— ลำตัวกลมและขุดโพรงเป็นลักษณะของ Sarcoptes ซึ่งอยู่คนละวงศ์\n— ปากดูดเลือดยาวกว่าลำตัวไม่ใช่ลักษณะของไรกลุ่มนี้\n— ลำตัวแบนข้างและเกาะเส้นขนเป็นลักษณะของเหา ไม่ใช่ไร\n— ไรไม่ได้มีลำตัวแปดปล้องและไม่มีตาแบบนั้น\n\n💡 Psoroptidae คือไรผิวเผิน ขายาวจนโผล่ให้เห็นจากข้างบน",
