    "explain": "ม้ามีต่อมน้ำลายสี่ต่อม คือ parotid mandibular sublingual และ dorsal buccal น้ำลายทำหน้าที่หล่อลื่นและเป็นบัฟเฟอร์ที่ pH ราว 8 ถึง 9 การเคี้ยวหญ้าจึงสำคัญเพราะหญ้าหนึ่งกิโลกรัมต้องเคี้ยวเกือบ 3,500 ครั้ง ทำให้หลั่งน้ำลายมากกว่าการกินอาหารเม็ด\n\n❌ ทำไมข้ออื่นผิด\n— สองและสามต่อมนับไม่ครบ ขาด dorsal buccal ไป\n— ม้าไม่มี zygomatic gland แยกออกมาในรายชื่อที่ใช้เรียน\n— หกต่อมเป็นการนับเกินโดยแยกต่อมเล็กที่ไม่นับแยกในบทเรียน\n\n💡 สี่ต่อม และตัวที่คนลืมบ่อยที่สุดคือ dorsal buccal",
