    "explain": "อาการโคลิกที่มองเห็นได้จากนอกคอกคือ pawing หรือคุ้ยเขี่ยพื้นด้วยขาหน้า หันมองสีข้าง ยืดตัว หายใจเร็ว เหงื่อออกมาก เตะท้องตัวเอง ล้มนอนและกลิ้ง ซึ่งการกลิ้งอันตรายมากเพราะเสี่ยงกระเพาะแตกและลำไส้บิด\n\n❌ ทำไมข้ออื่นผิด\n— การยืนอ้าขาหน้าและยื่นคอเป็นท่าของม้าที่หายใจลำบาก\n— การเดินวนและดันผนังคอกเป็นอาการทางระบบประสาท\n— การยกขาหลังพักสลับเป็นท่าพักปกติของม้า\n— การก้มหัวต่ำและน้ำลายไหลยืดเป็นลักษณะของ choke หรือปัญหาในช่องปาก\n\n💡 คุ้ยพื้น มองท้อง กลิ้ง คือสามสัญญาณที่เห็นได้จากหน้าคอก",
