    "q": "เมื่อม้าโคลิกมีการอักเสบหรือภาวะติดเชื้อในกระแสเลือด อวัยวะกลุ่มใดเป็นแหล่งผลิต lactate ที่ทำให้ค่าในเลือดสูงขึ้น",
    "options": [
      "ไต กระเพาะปัสสาวะ ต่อมหมวกไต และผิวหนัง",
      "ตับ กล้ามเนื้อ ปอด และทางเดินอาหาร",
      "สมอง ไขสันหลัง ต่อมไทรอยด์ และม้าม",
      "หัวใจ หลอดเลือดแดงใหญ่ และไขกระดูก",
      "ตับอ่อน ถุงน้ำดี ต่อมน้ำเหลือง และกระดูก"
    ],
    "answer": 1,
    "explain": "ในภาวะอักเสบหรือ sepsis อวัยวะที่ผลิต lactate เพิ่มขึ้นคือ ตับ กล้ามเนื้อ ปอด และทางเดินอาหาร ค่าที่วัดได้จึงใช้พยากรณ์โรคได้ ม้าปกติมีค่าต่ำกว่า 1 mmol/L ส่วนม้าโพนี่ไทยอาจอยู่ที่ 2.2 ถึง 3 ได้โดยยังไม่ผิดปกติ และการเจาะ peritoneal fluid ให้ค่าที่สะท้อนลำไส้ได้แม่นกว่าเลือด\n\n❌ ทำไมข้ออื่นผิด\n— ไตเป็นอวัยวะที่กำจัด lactate มากกว่าจะเป็นแหล่งผลิตหลัก\n— สมองและไขสันหลังไม่ใช่แหล่งผลิตหลักในบริบทของโคลิก\n— หัวใจและไขกระดูกไม่ใช่กลุ่มที่ใช้อธิบายค่าที่สูงขึ้นในเคสนี้\n— ตับอ่อนและถุงน้ำดีไม่เกี่ยว และม้าไม่มีถุงน้ำดีด้วย\n\n💡 ลำไส้ขาดเลือดคือต้นทาง แต่ค่าที่สูงมาจากหลายอวัยวะรวมกัน",
    "source": "Equine Med Mid 86.pdf p.17 (รวบรวมโดยรุ่นพี่ Vet 85)",
