    "q": "Rectal palpation ในม้าโคลิกให้ข้อมูลอะไรที่การตรวจอื่นทดแทนได้ยากที่สุด",
    "options": [
      "บอกชนิดของจุลชีพที่หมักอยู่ในลำไส้ใหญ่ส่วนท้าย",
      "บอกค่าความเป็นกรดด่างของคอนเทนต์ในลำไส้โดยตรง",
      "บอกตำแหน่งและการเคลื่อนผิดที่ของอวัยวะช่วงท้ายช่องท้อง",
      "บอกปริมาณเลือดที่ไหลเวียนผ่านหลอดเลือดที่เลี้ยงลำไส้",
      "บอกระดับความเจ็บปวดของม้าเป็นคะแนนได้อย่างแม่นยำ"
    ],
    "answer": 2,
    "explain": "การล้วงตรวจทางทวารหนักช่วยคลำอวัยวะช่วงท้ายของช่องท้องโดยตรง จึงบอกการขยายตัวของลำไส้ ตำแหน่งที่เคลื่อนผิดที่ เช่น nephrosplenic entrapment หรือ large colon displacement และคลำก้อนอุจจาระอัดแน่นที่ pelvic flexure ได้ แต่ต้องอาศัยประสบการณ์และทำอย่างระวังเพราะเสี่ยงฉีกขาด\n\n❌ ทำไมข้ออื่นผิด\n— ชนิดของจุลชีพต้องอาศัยการเพาะเชื้อหรือการวิเคราะห์ระดับโมเลกุล\n— ค่าความเป็นกรดด่างของคอนเทนต์ไม่ได้วัดด้วยการคลำ\n— ปริมาณเลือดที่ไหลเวียนต้องประเมินจากค่าเลือดและการอัลตราซาวด์\n— ระดับความเจ็บปวดประเมินจากพฤติกรรมและสัญญาณชีพ ไม่ใช่การคลำ\n\n💡 ล้วงเพื่อรู้ว่าอวัยวะย้ายไปอยู่ตรงไหน ไม่ใช่เพื่อรู้ว่าเชื้ออะไร",
    "source": "Equine Med Mid 86.pdf p.17 (รวบรวมโดยรุ่นพี่ Vet 85)",
