    "answer": 0,
    "explain": "ปัจจัยโน้มนำของโคลิกได้แก่ การเปลี่ยนอาหารหรือให้อาหารข้นมื้อใหญ่ น้ำดื่มไม่พอ ปรสิตในทางเดินอาหาร การกินทรายหรือกลืนลม ปัญหาฟันที่ทำให้บดเคี้ยวไม่ละเอียด การใช้ NSAID สิ่งแปลกปลอม อายุมาก และความเครียด\n\n❌ ทำไมข้ออื่นผิด\n— แสงแดด ความยาวขน และการอาบน้ำไม่ใช่ปัจจัยโน้มนำของโคลิก\n— สีขนและความสูงไม่เกี่ยวกับความเสี่ยงโคลิก\n— วัคซีน การแปรงขน และการแต่งกีบเป็นการดูแลปกติ ไม่ใช่ปัจจัยเสี่ยง\n— การให้หญ้าตลอดวันและการให้น้ำจากถังเป็นวิธีลดความเสี่ยง ไม่ใช่เพิ่ม\n\n💡 อาหาร น้ำ ฟัน พยาธิ ทราย ความเครียด คือหกคำที่ต้องถามทุกเคส",
