      "คาท่อไว้แล้วให้ม้าเดินออกกำลังเบาเพื่อกระตุ้นการบีบตัวของลำไส้",
      "เปลี่ยนไปให้อาหารข้นปริมาณมากเพื่อกระตุ้นการเคลื่อนของลำไส้"
