    "answer": 1,
    "explain": "คอนเทนต์ที่แห้งแปลว่าม้าขาดน้ำในทางเดินอาหาร การจัดการคือใส่น้ำหรือพาราฟินผ่านท่อแล้วดูดออกมาประเมินอีกครั้ง โดยต้องรู้ปริมาณที่ใส่เข้าไปเพราะกระเพาะม้าจุเพียงราว 8 ถึง 15 ลิตร ใส่เท่าไรต้องได้ออกมาใกล้เคียงกัน\n\n❌ ทำไมข้ออื่นผิด\n— คอนเทนต์แห้งอย่างเดียวไม่ใช่ข้อบ่งชี้ผ่าตัดทันที ต้องประเมินร่วมกับคะแนนรวม\n— การให้ยาแก้ปวดขนาดสูงแล้วรอนานอาจบังอาการจนพลาดเคสที่ต้องผ่าตัด\n— ห้ามคาท่อไว้ในตัวม้าโดยไม่มีคนเฝ้าเพราะอันตรายมาก\n— การให้อาหารข้นในม้าที่กำลังโคลิกทำให้แย่ลง\n\n💡 แห้งคือขาดน้ำ ใส่น้ำแล้วดูดออกมาดูใหม่ และนับปริมาณให้ครบ",
