    "explain": "การให้เกรดแผลในกระเพาะม้าแบ่งเป็น 0 ถึง 4 โดย 0 คือปกติ 1 คือ hyperkeratosis ที่ล้างแล้วไม่หลุด 2 และ 3 คือเยื่อบุแหว่งเป็นแผลมากขึ้นตามลำดับ และ 4 คือ deep ulceration ที่ลึกลงไปถึงชั้นใต้เยื่อบุ การให้เกรดต้องส่องกล้องหลังงดอาหารและฉีดน้ำล้างก่อน\n\n❌ ทำไมข้ออื่นผิด\n— เยื่อบุปกติคือ grade 0\n— hyperkeratosis ที่ล้างไม่หลุดคือ grade 1\n— แผลตื้นกระจายอยู่ในช่วง grade 2 ถึง 3\n— จุดเลือดคั่งที่ยังไม่แหว่งยังไม่ถึงเกณฑ์ deep ulceration\n\n💡 ไล่จาก 0 ปกติ 1 หนา 2 กับ 3 แหว่ง และ 4 ลึก",
