    "q": "ม้าลูกผสมเพศผู้ตอน อายุ 12 ปี น้ำหนัก 480 กิโลกรัม ขาหน้าซ้ายเจ็บจึงถูกพักในคอกมาสองสัปดาห์ เจ้าของแจ้งว่าวันนี้กินอาหารน้อยลง ถ่ายน้อยและแห้ง มีอาการคุ้ยพื้นเป็นระยะ ตรวจพบ HR 44 ครั้งต่อนาที RR 20 ครั้งต่อนาที Temp 100.4 F เยื่อเมือกชมพู CRT 2 วินาที gut sound ลดลงทั้งสี่จุด สอด NG tube ได้คอนเทนต์ 0.3 ลิตร ไม่มี reflux จงระบุการวินิจฉัยที่น่าจะเป็นมากที่สุด แนวทางรักษาเบื้องต้น และวิธีป้องกันไม่ให้เกิดซ้ำ",
    "keywords": [
      "pelvic flexure impaction",
      "rectal palpation",
      "nasogastric",
      "paraffin",
      "IV fluid",
      "analgesia",
      "exercise",
      "water intake"
    ],
    "model_answer": "การวินิจฉัยที่น่าจะเป็นมากที่สุดคือ pelvic flexure impaction เพราะเป็นม้าที่ถูกจำกัดการเคลื่อนไหวจากขาเจ็บ ถ่ายน้อยและแห้ง ปวดไม่รุนแรง สัญญาณชีพยังใกล้ปกติ และไม่มี gastric reflux ซึ่งบอกว่าการอุดตันอยู่ต่ำกว่าลำไส้เล็ก\n\nการยืนยันทำโดยล้วงตรวจทางทวารหนักเพื่อคลำก้อนอัดแน่นที่ pelvic flexure ในช่องท้องด้านซ้ายล่าง ร่วมกับอัลตราซาวด์และประเมินระดับความเจ็บซ้ำเป็นระยะ\n\nแนวทางรักษาเบื้องต้นคือ ให้น้ำและพาราฟินออยล์ผ่าน nasogastric tube ร่วมกับสารน้ำทางหลอดเลือดดำเพื่อทำให้ก้อนอุจจาระนุ่มลง งดอาหารจนกว่าจะถ่าย ให้ยาระงับปวดเท่าที่จำเป็น เช่น flunixin meglumine หรือ xylazine โดยคำนึงว่ายาอาจบังอาการ และประเมินซ้ำทุกไม่กี่ชั่วโมง ถ้าอาการปวดรุนแรงขึ้น คะแนนรวมสูงขึ้น หรือไม่ตอบสนองใน 24 ถึง 48 ชั่วโมง ให้พิจารณาผ่าตัด\n\nการป้องกันคือ ให้ม้าได้เคลื่อนไหวหรือเดินเบาทุกวันแม้อยู่ในช่วงพักฟื้น ให้อาหารหยาบบ่อยครั้งตลอดวันแทนมื้อใหญ่ห่างกัน จัดน้ำสะอาดให้กินจากถังเพื่อวัดปริมาณได้และไม่ให้น้ำเย็นเกิน ตรวจฟันตามรอบเพื่อให้บดเคี้ยวได้ละเอียด และถ่ายพยาธิตามผลนับไข่",
    "explain": "ชุดข้อมูลนี้คือลายเซ็นของ impaction ที่ pelvic flexure คือม้าที่ไม่ได้เคลื่อนไหว ถ่ายน้อยและแห้ง ปวดไม่รุนแรง และไม่มี reflux เพราะจุดอุดตันอยู่ไกลจากกระเพาะ\n\n💡 ไม่มี reflux แปลว่าปัญหาอยู่ต่ำกว่าลำไส้เล็ก และม้าที่ยืนนิ่งคือม้าที่ลำไส้ก็นิ่งตาม",
