    "q": "ม้าไทยพันธุ์ผสมเพศเมีย อายุ 8 ปี เลี้ยงในคอกดินทรายและให้อาหารบนพื้น มีประวัติปวดท้องเป็นพักเป็นระยะมาหนึ่งเดือน ถ่ายเหลวสลับปกติ ผอมลงช้า ฟังท้องด้านขวาล่างได้ยินเสียงคล้ายคลื่นซัดฝั่ง จงระบุการวินิจฉัยที่น่าจะเป็น วิธีตรวจยืนยันอย่างง่ายที่ทำได้ในฟาร์ม แนวทางรักษา และวิธีป้องกัน",
    "keywords": [
      "sand colic",
      "sand sedimentation test",
      "psyllium",
      "paraffin",
      "feeding off the ground",
      "rubber mat",
      "ultrasound"
    ],
    "model_answer": "การวินิจฉัยที่น่าจะเป็นคือ sand colic หรือ sand accumulation ในลำไส้ใหญ่ เพราะเลี้ยงบนพื้นทราย ให้อาหารบนพื้น ปวดท้องเป็นพักเป็นระยะ ถ่ายเหลวสลับปกติ และได้ยินเสียงคล้ายคลื่นซัดฝั่งจากทรายที่เคลื่อนใน ventral colon\n\nการตรวจยืนยันอย่างง่ายในฟาร์มคือ sand sedimentation test นำอุจจาระราวหกก้อนใส่ถุงมือหรือแก้วใส เติมน้ำแล้วตั้งทิ้งไว้ ทรายจะตกตะกอนอยู่ก้นภาชนะ ถ้ามีในหน่วยช้อนชาขึ้นไปถือว่ามีนัยสำคัญ ยืนยันเพิ่มด้วยอัลตราซาวด์ช่องท้องด้านล่างและภาพรังสีช่องท้องในรายที่ทำได้\n\nแนวทางรักษาคือ ให้ psyllium ผ่าน nasogastric tube หรือผสมอาหารร่วมกับพาราฟินออยล์และสารน้ำ ให้อาหารหยาบคุณภาพดีเพื่อเพิ่มการเคลื่อนของลำไส้ ควบคุมความเจ็บปวด และติดตามปริมาณทรายในอุจจาระซ้ำ รายที่อุดตันมากหรือไม่ตอบสนองต้องผ่าตัดเอาทรายออก\n\nการป้องกันคือ ห้ามให้อาหารบนพื้นทราย ใช้รางหรือยางปูรองพื้นบริเวณให้อาหาร ให้หญ้าเพียงพอเพื่อไม่ให้ม้าเล็มดินเพราะหิว และให้ psyllium เป็นรอบตามคำแนะนำในพื้นที่เสี่ยง",
    "explain": "การเลี้ยงบนพื้นทรายบวกกับการให้อาหารบนพื้นเป็นชุดประวัติที่ชี้ตรงไปที่ sand colic เสียงคล้ายคลื่นซัดฝั่งเกิดจากทรายที่เคลื่อนไปมาใน ventral colon และ sedimentation test เป็นการตรวจที่ทำได้ทันทีหน้าคอก\n\n💡 พื้นทรายกับชามอาหารที่วางกับพื้น คือสองสิ่งที่ต้องถามก่อนเสมอในเคสปวดท้องเรื้อรัง",
    "source": "Equine Med Mid 86.pdf p.19 (รวบรวมโดยรุ่นพี่ Vet 85)",
