    "explain": "Heave line คือแนวสันที่เกิดจาก external abdominal oblique หนาตัวขึ้น เพราะม้าต้องออกแรงหายใจออกมากผิดปกติเป็นเวลานาน พบในม้าที่เป็น equine asthma หรือ recurrent airway obstruction จึงเป็นสัญญาณของโรคทางเดินหายใจส่วนล่างแบบเรื้อรัง\n\n❌ ทำไมข้ออื่นผิด\n— ไขมันในม้าอ้วนสะสมที่สันคอ โคนหาง และหลัง ไม่ได้เป็นแนวสันตามชายโครง\n— กระดูกซี่โครงนูนจากการบาดเจ็บจะเป็นจุดเดียว ไม่ใช่แนวยาว\n— หลอดเลือดดำโป่งพองจะเห็นเป็นเส้นเลือดใต้ผิวหนัง ไม่ใช่สันกล้ามเนื้อ\n— ผิวหนังหนาจากสายรัดจะอยู่ตรงแนวสายรัดหลังข้อศอก ไม่ใช่ตามชายโครง\n\n💡 เห็นสันตามชายโครง แปลว่าม้าตัวนี้ออกแรงหายใจออกมานานแล้ว",
