    "explain": "TTW เจาะผ่านผนังหลอดลมโดยตรงจึงเลี่ยงการปนเปื้อนจากทางเดินหายใจส่วนต้น เหมาะกับการเพาะเชื้อและย้อมสี แต่สะท้อนเฉพาะสิ่งที่ถูกพัดขึ้นมาถึงหลอดลม ส่วน BAL สอดผ่านจมูกลงไปล้างถึงถุงลม จึงสะท้อนปอดส่วนลึกและอ่านผลด้วยการนับสัดส่วนเซลล์ แต่ปนเปื้อนจากทางเดินหายใจส่วนต้นได้\n\n❌ ทำไมข้ออื่นผิด\n— บทบาทของทั้งสองวิธีถูกสลับกันในตัวเลือกนี้\n— TTW ทำในม้ายืนที่ได้ยาซึมและยาชาเฉพาะที่ ไม่ต้องวางยาสลบ และ BAL ก็ต้องให้ยาซึม\n— ผลของสองวิธีไม่เหมือนกัน จึงเลือกตามคำถามทางคลินิก\n— ทั้งสองวิธีใช้ได้ทั้งลูกม้าและม้าโต ไม่ได้จำกัดตามอายุ\n\n💡 อยากเพาะเชื้อให้เจาะคอ อยากรู้ว่าปอดอักเสบแบบไหนให้ล้างถึงถุงลม",
