    "explain": "สายระบายที่คาไว้ในโพรงไซนัสต้องเย็บยึดกับผิวหนังด้วยแบบ Chinese finger trap ซึ่งพันไหมรอบสายเป็นชุดปมไขว้ ทำให้ยิ่งดึงยิ่งรัดแน่น จึงกันสายเลื่อนหลุดเมื่อม้าสะบัดหัวหรือถูกถู เป็นวิธีมาตรฐานเดียวกับที่ใช้ยึด chest drain\n\n❌ ทำไมข้ออื่นผิด\n— พลาสเตอร์อย่างเดียวหลุดง่ายเพราะขนและเหงื่อของม้า\n— การผูกสายกับขลุมทำให้สายถูกดึงรั้งทุกครั้งที่ม้าขยับหัว\n— กาวติดเนื้อเยื่อไม่แข็งแรงพอสำหรับแรงดึงของม้า\n— การสอดลึกจนติดผนังไซนัสทำให้เยื่อบุบาดเจ็บและระบายไม่ออก\n\n💡 Chinese finger trap คือยิ่งดึงยิ่งแน่น จึงเป็นปมประจำของสายที่ต้องคาไว้",
