    "q": "ขณะม้าควบเต็มฝีเท้า อัตราการหายใจและปริมาตรอากาศที่ผ่านปอดเปลี่ยนไปอย่างไร",
    "options": [
      "ราว 30 ครั้งต่อนาที และอากาศผ่านปอดราว 200 ลิตรต่อนาที",
      "ราว 60 ครั้งต่อนาที และอากาศผ่านปอดราว 600 ลิตรต่อนาที",
      "ราว 120 ครั้งต่อนาที และอากาศผ่านปอดราว 1,800 ลิตรต่อนาที",
      "ราว 200 ครั้งต่อนาที และอากาศผ่านปอดราว 3,000 ลิตรต่อนาที",
      "ราว 45 ครั้งต่อนาที และอากาศผ่านปอดราว 100 ลิตรต่อนาที"
    ],
    "answer": 2,
    "explain": "ขณะควบเต็มฝีเท้าม้าหายใจล็อกกับจังหวะย่างก้าว ได้ราว 120 ครั้งต่อนาที ปริมาตรต่อครั้งราว 15 ลิตร รวมเป็นอากาศที่ผ่านปอดราว 1,800 ลิตรต่อนาที และอากาศเดินทางจากรูจมูกถึงถุงลมในเวลาราว 0.25 วินาที ตัวเลขชุดนี้อธิบายว่าเหตุใดการอุดตันทางเดินหายใจส่วนต้นเพียงเล็กน้อยจึงทำให้ม้าแข่งทำผลงานตกทันที\n\n❌ ทำไมข้ออื่นผิด\n— 30 ครั้งต่อนาทีใกล้เคียงกับม้าที่ยืนพัก ไม่ใช่ขณะควบ\n— 60 ครั้งต่อนาทีและ 600 ลิตรต่ำกว่าค่าจริงราวครึ่งหนึ่ง\n— 200 ครั้งต่อนาทีสูงเกินจริง เพราะการหายใจล็อกกับจังหวะก้าว\n— 45 ครั้งต่อนาทีกับ 100 ลิตรเป็นค่าของการออกกำลังเบา\n\n💡 ม้าหายใจหนึ่งครั้งต่อหนึ่งก้าว ยิ่งวิ่งเร็วยิ่งหายใจถี่ตามฝีเท้า",
