    "explain": "ชื่อของปื้นขาวที่ขาเรียกตามระดับสูงสุดที่ขนขาวขึ้นไปถึง ไล่จากล่างขึ้นบนคือ coronet แล้ว half pastern แล้ว pastern แล้ว fetlock แล้ว half cannon แล้ว cannon เมื่อขาวคลุมถึงข้อ fetlock พอดีจึงบันทึกว่า fetlock\n\n❌ ทำไมข้ออื่นผิด\n— Coronet คือขาวแคบแค่แนวขอบกีบ ต่ำกว่าโจทย์มาก\n— Half pastern คือขาวถึงครึ่งของกระดูก pastern ยังไม่ถึง fetlock\n— Half cannon และ cannon สูงเกินข้อ fetlock ขึ้นไปบนกระดูกแข้ง\n\n💡 เรียกตามข้อที่ขาวไปถึง ไม่ใช่ตามความกว้างของปื้น",
