    "q": "จากภาพจุดสังเกตบนตัวม้าเทียบกับโครงกระดูก ข้อใดจับคู่ชื่อจุดสังเกตภายนอกกับโครงสร้างกระดูกที่รองอยู่ได้ถูกต้อง",
