    "q": "เดินเข้าไปในคอก พบม้ายืนนิ่ง คอผ่อนคลาย ใบหูทั้งสองข้างตกไปทางด้านข้างของศีรษะ ตาปรือ ริมฝีปากล่างหย่อน ท่าทางชุดนี้บ่งบอกอะไร",
