      "เจาะช่องอกดูดของเหลวส่งตรวจ เพราะสงสัยน้ำในช่องเยื่อหุ้มปอด",
      "ป้าย swab ที่ nasopharynx ส่งตรวจหาเชื้อไวรัสทางเดินหายใจ"
